import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void exchangeKeepsObjects(){Object a=TaskBinding.create(3),b=TaskBinding.create(8);Object oldA=a,oldB=b;TaskBinding.swap(a,b);assertSame(oldA,a);assertSame(oldB,b);assertEquals(8,TaskBinding.value(a));assertEquals(3,TaskBinding.value(b));}}
